// Config: edit these values once. Every other node reads them via $('Config').first().json
// If n8n runs in Docker and Neo4j/Ollama run on the host, use host.docker.internal.
// If n8n runs directly on Windows (npm / desktop), use localhost.
return [{
  json: {
    neo4j_url: 'http://host.docker.internal:7474',
    neo4j_db: 'neo4j',
    ollama_url: 'http://host.docker.internal:11434',
    embed_model: 'nomic-embed-text',
    // Scryfall set code(s) to ingest. One set is ~250-300 cards. Space separated for several: 'fdn dsk'
    set_codes: 'fdn',
    // Paste the current TXT link from https://magic.wizards.com/en/rules
    cr_url: 'PASTE_COMPREHENSIVE_RULES_TXT_URL_HERE',
  },
}];

// Input: Scryfall /cards/search pages (one item per page, cards in .data[])
// Output: one item per unique card (oracle_id), flattened for the graph import.
const SUPERTYPES = new Set(['Basic', 'Legendary', 'Ongoing', 'Snow', 'World']);
const FORMATS = ['standard', 'pioneer', 'modern', 'legacy', 'vintage', 'commander', 'pauper'];

const cards = $input.all().flatMap(i => (Array.isArray(i.json.data) ? i.json.data : []));
const seen = new Set();
const out = [];

for (const c of cards) {
  if (!c.oracle_id || seen.has(c.oracle_id)) continue;
  seen.add(c.oracle_id);

  // Double-faced, split and adventure cards keep their text in card_faces
  const faces = Array.isArray(c.card_faces) && c.card_faces.length ? c.card_faces : [c];

  const supertypes = new Set();
  const types = new Set();
  const subtypes = new Set();
  for (const f of faces) {
    const [left, right = ''] = String(f.type_line ?? c.type_line ?? '').split(' — ');
    for (const w of left.trim().split(/\s+/).filter(Boolean)) (SUPERTYPES.has(w) ? supertypes : types).add(w);
    for (const w of right.trim().split(/\s+/).filter(Boolean)) subtypes.add(w);
  }

  const pt = faces.find(f => f.power != null);
  const colors = c.colors ?? [...new Set(faces.flatMap(f => f.colors ?? []))];

  out.push({
    json: {
      oracle_id: c.oracle_id,
      scryfall_id: c.id,
      name: c.name,
      mana_cost: c.mana_cost ?? faces.map(f => f.mana_cost ?? '').join(' // '),
      mana_value: c.cmc ?? 0,
      type_line: c.type_line ?? faces.map(f => f.type_line).join(' // '),
      oracle_text: faces.map(f => f.oracle_text ?? '').filter(Boolean).join('\n//\n'),
      power: pt?.power ?? null,
      toughness: pt?.toughness ?? null,
      loyalty: faces.find(f => f.loyalty != null)?.loyalty ?? null,
      rarity: c.rarity,
      colors,
      color_identity: c.color_identity ?? [],
      supertypes: [...supertypes],
      types: [...types],
      subtypes: [...subtypes],
      keywords: c.keywords ?? [],
      set_code: c.set,
      set_name: c.set_name,
      legal_formats: FORMATS.filter(f => ['legal', 'restricted'].includes(c.legalities?.[f])),
      scryfall_uri: c.scryfall_uri,
    },
  });
}

if (!out.length) throw new Error('No cards returned from Scryfall - check set_codes in Config');
return out;

// Wraps card rows in Neo4j HTTP transaction bodies (UNWIND batches of 100).
const STATEMENT = "UNWIND $rows AS row
MERGE (c:Card {oracle_id: row.oracle_id})
SET c.name = row.name, c.mana_cost = row.mana_cost, c.mana_value = row.mana_value,
    c.type_line = row.type_line, c.oracle_text = row.oracle_text,
    c.power = row.power, c.toughness = row.toughness, c.loyalty = row.loyalty,
    c.rarity = row.rarity, c.scryfall_uri = row.scryfall_uri
MERGE (s:Set {code: row.set_code}) SET s.name = row.set_name
MERGE (c)-[:PRINTED_IN]->(s)
FOREACH (x IN row.colors         | MERGE (n:Color {code: x})     MERGE (c)-[:HAS_COLOR]->(n))
FOREACH (x IN row.color_identity | MERGE (n:Color {code: x})     MERGE (c)-[:HAS_COLOR_IDENTITY]->(n))
FOREACH (x IN row.supertypes     | MERGE (n:Supertype {name: x}) MERGE (c)-[:HAS_SUPERTYPE]->(n))
FOREACH (x IN row.types          | MERGE (n:CardType {name: x})  MERGE (c)-[:IS_TYPE]->(n))
FOREACH (x IN row.subtypes       | MERGE (n:Subtype {name: x})   MERGE (c)-[:HAS_SUBTYPE]->(n))
FOREACH (x IN row.keywords       | MERGE (n:Keyword {name: x})   MERGE (c)-[:HAS_KEYWORD]->(n))
FOREACH (x IN row.legal_formats  | MERGE (n:Format {name: x})    MERGE (c)-[:LEGAL_IN]->(n))";
const BATCH = 100;

const rows = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  out.push({ json: { statements: [{ statement: STATEMENT, parameters: { rows: rows.slice(i, i + BATCH) } }] } });
}
return out;

// The Neo4j HTTP API returns 200 even when Cypher fails, so fail loudly here.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) throw new Error('Neo4j error: ' + JSON.stringify(errors));
}
return [{ json: { ok: true, batches: $input.all().length } }];

// Builds one chunk per card and one chunk per card's rulings.
// Input: responses from Scryfall /cards/{id}/rulings, in the same order as 'Normalize cards'.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const cards = $('Normalize cards').all().map(i => i.json);
const rulings = $input.all().map(i => i.json);
const out = [];

cards.forEach((c, idx) => {
  const stats = c.power != null ? `${c.power}/${c.toughness}` : c.loyalty != null ? `Loyalty ${c.loyalty}` : null;
  const cardText = [
    `${c.name} ${c.mana_cost ?? ''}`.trim(),
    c.type_line,
    c.oracle_text,
    stats,
    `Set: ${c.set_name} (${String(c.set_code).toUpperCase()})`,
  ].filter(Boolean).join('\n');

  out.push({
    json: {
      chunk_id: `card:${c.oracle_id}`,
      source_type: 'card',
      parent_id: c.oracle_id,
      text: cardText,
      hash: fnv1a(cardText),
      source: `Scryfall: ${c.name} (${c.scryfall_uri})`,
    },
  });

  const list = Array.isArray(rulings[idx]?.data) ? rulings[idx].data : [];
  if (list.length) {
    const rulingText = [`Official rulings for ${c.name}:`, ...list.map(r => `- (${r.published_at}) ${r.comment}`)].join('\n');
    out.push({
      json: {
        chunk_id: `rulings:${c.oracle_id}`,
        source_type: 'ruling',
        parent_id: c.oracle_id,
        text: rulingText,
        hash: fnv1a(rulingText),
        source: `Scryfall rulings: ${c.name} (${c.scryfall_uri})`,
      },
    });
  }
});

return out;

// Duplicate check: ask Neo4j which chunks already exist and with which content hash.
const ids = $input.all().map(i => i.json.chunk_id);
return [{
  json: {
    statements: [{
      statement: 'MATCH (ch:Chunk) WHERE ch.id IN $ids RETURN ch.id AS id, ch.hash AS hash',
      parameters: { ids },
    }],
  },
}];

// Keep only new chunks or chunks whose text changed. Unchanged chunks are not re-embedded.
const res = $input.first().json;
if (res.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(res.errors));
const existing = new Map((res.results?.[0]?.data ?? []).map(d => [d.row[0], d.row[1]]));

const chunks = $("Build card chunks").all().map(i => i.json);
const changed = chunks.filter(c => existing.get(c.chunk_id) !== c.hash);
const skipped = chunks.length - changed.length;
console.log(`Chunks: ${chunks.length}, unchanged (skipped): ${skipped}, to embed: ${changed.length}`);
return changed.map(c => ({ json: c }));

// 32 texts per request instead of one request per chunk.
// n8n's HTTP node fires all items concurrently by default, which floods Ollama
// (requests queue up and Docker's proxy starts refusing connections).
const BATCH = 32;
const chunks = $input.all().map(i => i.json);
const out = [];
for (let i = 0; i < chunks.length; i += BATCH) {
  out.push({ json: { inputs: chunks.slice(i, i + BATCH).map(c => 'search_document: ' + c.text) } });
}
return out;

// Each Ollama response holds up to 32 embeddings; flatten them back onto the chunks in order.
const chunks = $('Filter changed chunks').all().map(i => i.json);
const embeddings = $input.all().flatMap(i => i.json.embeddings ?? []);
if (embeddings.length !== chunks.length) {
  throw new Error(`Got ${embeddings.length} embeddings for ${chunks.length} chunks`);
}
return chunks.map((c, idx) => ({ json: { ...c, embedding: embeddings[idx] } }));

// Upserts chunks with their embedding. Label and parent link depend on the chunk type.
const BASE = "UNWIND $rows AS row\nMERGE (ch:Chunk {id: row.chunk_id})\nSET ch:__LABEL__, ch.text = row.text, ch.source = row.source,\n    ch.source_type = row.source_type, ch.hash = row.hash, ch.embedding = row.embedding\nWITH ch, row\n__LINK__";
const LABEL = { card: 'CardChunk', ruling: 'RulingChunk', rule: 'RuleChunk' };
const LINK = {
  card: 'MATCH (p:Card {oracle_id: row.parent_id}) MERGE (p)-[:HAS_CHUNK]->(ch)',
  ruling: 'MATCH (p:Card {oracle_id: row.parent_id}) MERGE (p)-[:HAS_RULINGS]->(ch)',
  rule: 'MATCH (p:Rule {number: row.parent_id}) MERGE (p)-[:HAS_CHUNK]->(ch)',
};
const BATCH = 50;

const byType = {};
for (const { json: c } of $input.all()) {
  (byType[c.source_type] ??= []).push({
    chunk_id: c.chunk_id, parent_id: c.parent_id, source_type: c.source_type,
    text: c.text, hash: c.hash, source: c.source, embedding: c.embedding,
  });
}

const out = [];
for (const [type, rows] of Object.entries(byType)) {
  const statement = BASE.replace('__LABEL__', LABEL[type]).replace('__LINK__', LINK[type]);
  for (let i = 0; i < rows.length; i += BATCH) {
    out.push({ json: { statements: [{ statement, parameters: { rows: rows.slice(i, i + BATCH) } }] } });
  }
}
return out;

// Links Keyword nodes (from Scryfall) to the Comprehensive Rule that defines them (701.x / 702.x).
for (const item of $input.all()) {
  if (item.json.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(item.json.errors));
}
return [{ json: { statements: [{ statement: "MATCH (k:Keyword)\nMATCH (r:Rule {level: 'rule'})\nWHERE r.section IN ['701', '702'] AND toLower(r.title) = toLower(k.name)\nMERGE (k)-[:DEFINED_BY]->(r)\nRETURN count(*) AS linked", parameters: {} }] } }];

// The Neo4j HTTP API returns 200 even when Cypher fails, so fail loudly here.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) throw new Error('Neo4j error: ' + JSON.stringify(errors));
}
return [{ json: { ok: true, batches: $input.all().length } }];
